var v=Object.defineProperty;var c=(w,k)=>v(w,"name",{value:k,configurable:!0});import{jsxs as t,jsx as e}from"react/jsx-runtime";import{$ as T}from"@dna-platform/chemistry";import{$ as M,I,D as S,M as s,O as r,S as h}from"./.cover-w2L6MDLA.js";import{A as d}from"./1-the-action-and-the-result~code-9d0ewh26.js";import{T as A,a as P}from"./.synopsis-CDL0AnCJ.js";import{Chapter as f,TableOfContents as X,Title as b,Parenthetical as m,Section as x,Heading as C,Paragraph as n,Content as u,Word as a,Date as W,Bold as o,Emphasis as i,List as p,Line as l}from"@dna-platform/public";import"styled-components";import"./.cover-CeUTG1MA.js";import"./.cover-BzAVUNvr.js";const g=class g extends M{};c(g,"$ClaudeXMoneysUsLaunchAndFinancialCompetitionA8e9cd85");let y=g;const N=c(()=>t(f,{children:[e(X,{}),e(I,{}),t(b,{children:[e(m,{}),"[Table of Contents](/claude-x-moneys-us-launch-and-financial-competition-a8e9cd85/#table-of-contents)"]}),t(x,{children:[e(C,{children:"June 2026"}),e(n,{children:e(u,{children:"[30 June 2026](/claude-x-moneys-us-launch-and-financial-competition-a8e9cd85/#30-june-2026)"})}),t(n,{children:[e(m,{}),e(a,{children:e(u,{children:"[X Money's US launch and financial competition](/claude-x-moneys-us-launch-and-financial-competition-a8e9cd85/)"})}),e(a,{children:e(u,{children:"[Synopsis](/claude-x-moneys-us-launch-and-financial-competition-a8e9cd85/#synopsis)"})}),e(a,{children:e(u,{children:"[Table of Contents](/claude-x-moneys-us-launch-and-financial-competition-a8e9cd85/#table-of-contents)"})})]})]})]}),"Table"),j=c(()=>t(f,{children:[e(S,{children:e(W,{children:"[30 June 2026](2026-06-30)"})}),e(b,{children:"[30 June 2026](/claude-x-moneys-us-launch-and-financial-competition-a8e9cd85/#30-june-2026)"}),t(s,{at:"2026-06-30T13:16:06.171666Z",children:[e(r,{children:"019f18ac-b6fc-7ef6-9ab1-8cf4fc8e2f16"}),e(h,{children:"[Doug](/dougs-story/)"}),e(n,{children:"Talk to me about Musk’s X Money? Who is this a competition for in the US? Venmo? What’s the analysis on the Twitter social network based connecting through his financial application and how to cryptocurrency factor in? Is he helping to support stable coins or is that not a part of the plan?"})]}),t(s,{at:"2026-06-30T13:16:50.870417Z",children:[e(r,{children:"019f18ac-b6fd-7f7c-93d7-ae58ee53de7e"}),e(h,{children:"[Claude](/dougs-claude/)"}),e(d,{children:"Searched the web for “X Money Musk payments launch 2026”"}),e(d,{children:"Searched the web for “X Money stablecoin GENIUS Act Musk crypto integration plans”"}),e(n,{children:"Good timing to ask — X Money went fully live for US Premium subscribers on June 26, just days ago, ending a long beta. A user sent $25 directly to Musk to test the P2P feature and he confirmed it publicly. So this is now a real, shipping product, not vaporware."}),t(n,{children:[t(a,{children:[e(o,{}),"What it actually is right now."]})," A conventional fiat banking-and-payments layer bolted onto the social graph. The feature set: peer-to-peer transfers, FDIC-insured deposits, a personalized metal Visa debit card stamped with your handle, 3% cashback, zero foreign transaction fees — plus a much-discussed 6% APY on balances. Notably, the initial rollout is exclusively fiat; crypto functionality is not included at launch. Regulatory footprint: money-transmitter licenses in 41 states plus DC, but not yet New York or Massachusetts, two of the largest markets and the binding constraint on scale."]}),t(n,{children:[t(a,{children:[e(o,{}),"Who it's competing for."]}),` Venmo is the obvious P2P comparison, but that undersells it. The 3% cashback and zero FX fees aim at credit cards; the 6% APY and "you won't need a bank account" framing target traditional banking and money-market funds directly. So the real competitive set is Venmo + Cash App (Block) + PayPal + Apple Pay`,t(a,{children:[e(i,{}),"and"]})," the deposit base of conventional banks. The structural threat isn't product quality — the argument is that fintechs like Robinhood can't compete because X has ~550 million monthly users, and X doesn't need the best product, just a good-enough one inside the app people already live in. That's the whole thesis."]}),t(n,{children:[t(a,{children:[e(o,{}),"The social-graph-as-rail logic."]}),` This is the WeChat play, explicit and longstanding. Musk has said X could become "the biggest financial institution in the world" and that you should be able to "live your life on the X app." The distribution advantage is genuinely the asset here: payments embedded in the feed, identity already verified for monetization, network effects on who you can pay (anyone with a handle). The skeptic's counter, from payments veteran Richard Crone: "He promised this vision more than two years ago... this may be a day late and a dollar short" — and there's a real open question whether a platform built for conversation can be trusted as a reliable financial intermediary.`]}),t(n,{children:[t(a,{children:[e(o,{}),"The 6% yield is the tell worth watching."]})," With fed funds at 3.5–3.75%, it's unclear what mechanism funds a 6% yield — whether it's subsidized to drive adoption, generated by lending deposits, or something else, and that matters enormously for how regulators treat it. X Money isn't a stablecoin product, but it targets the exact same demand — people wanting better returns than their bank — through a different regulatory path. That arbitrage is the interesting part."]}),t(n,{children:[t(a,{children:[e(o,{}),"Crypto / stablecoins."]}),` No crypto at launch, but the door is deliberately left open. Musk hasn't explicitly said X Money will transact in crypto; he's amplified a third-party post speculating about "crypto integration" — characteristically non-committal. The substantive thread is the stablecoin one. The GENIUS Act (and the STABLE Act) dropped the prohibition on non-banking companies issuing stablecoins that earlier bills had — opening the door for Big Tech like Musk and Zuckerberg to issue their own. Warren has zeroed in on this "suspicious carveout" and pointedly asked whether Musk had a hand in it, given he was a special government employee while the GENIUS Act was being debated.`]}),e(n,{children:"So to your direct question — is he supporting stablecoins or not? The honest read: not yet operationally, but the regulatory groundwork was laid (possibly with his involvement) for X to issue its own. Chamath's argument is that X Money will accelerate stablecoin adoption and route the profits to users rather than the platform. The fiat-first launch is best understood as a cleaner regulatory on-ramp — establish insured deposits and a licensed-transmitter narrative first, add the stablecoin rail once the legal cover is settled."}),e(n,{children:'One connection to your own terrain: this is the same "everything app" archetype Telegram/TON is building, just inverted. Telegram went crypto-native first (TON as the rail, fiat as the afterthought); X is going fiat-first with a crypto option held in reserve. Two routes to WeChat — one starting from a payments license and a Visa partnership, one starting from a blockchain and a refusal to touch the banking system. Worth tracking which architecture the GENIUS Act regime actually advantages.'}),e(n,{children:`(Light flag: the 6% APY and "you won't need a bank account" claims are X's own marketing, and several details here — funding mechanism, NY approval timing, any stablecoin — remain unsettled and Musk-dependent, so I'd weight the present-tense facts above the forward promises.)`})]}),t(s,{at:"2026-06-30T13:19:21.458257Z",children:[e(r,{children:"019f18af-b177-7139-8cdc-423e06d54b5a"}),e(h,{children:"[Doug](/dougs-story/)"}),e(n,{children:"This is where it looks like a Telegram competitor, but in the world where you can use standard finance to provide this sort of thing. I’m pretty sure I’ve read that there was inspiration there and so I find it interesting"})]}),t(s,{at:"2026-06-30T13:20:15.492330Z",children:[e(r,{children:"019f18af-b178-7c22-ac6e-d75b5a65f8a1"}),e(h,{children:"[Claude](/dougs-claude/)"}),e(d,{children:"Searched the web for “Musk X everything app Telegram inspiration Durov”"}),e(d,{children:"Searched the web for “X Money compared Telegram Wallet TON payments super app rival”"}),e(n,{children:'Let me refine this a bit, because I think the genealogy is slightly different from "Telegram was the inspiration" — and the difference is interesting.'}),t(n,{children:["On the documented record, the model Musk actually ",t(a,{children:[e(i,{}),"names"]}),` is consistently WeChat / the Chinese super-apps, not Telegram. He's said X could become "the biggest financial institution in the world," explicitly pointing to how consumers in India and China use one app for social, messaging and payments. And the deeper root is his own: the "everything app" idea traces to `,t(a,{children:[e(o,{}),"X.com (1999)"]}),", Musk's original online bank that merged into PayPal — the 2026 debut of X Money is best read as a return to that 25-year-old vision of a single borderless financial destination. So the through-line is WeChat-as-template plus Musk finishing the thing he started before Twitter existed. I can't find a source where he credits Telegram as the inspiration — if you've got one, point me at it, because that would update me (and it's the kind of claim where you and I could both be misremembering a structural parallel as a stated lineage)."]}),t(n,{children:[`But the structural insight you're putting your finger on is real and sharper than the "inspiration" framing:`,t(a,{children:[e(o,{}),"Telegram/TON is the one Western-facing competitor that already built the chat-native everything-app with payments — just crypto-first instead of fiat-first."]}),` That's the actual symmetry. Durov envisioned TON precisely to integrate currency into chats and monetize via in-app money; the TON Foundation's stated goal was converting ~30% of Telegram's billion users into on-chain users. Commentators now explicitly bracket the two: TON Pay turning Telegram into a crypto checkout layer is described in the same breath as X Money as parallel "everything app" pushes. Two routes to the same destination — X starting from a money-transmitter license and a Visa deal, Telegram starting from a blockchain and refusing the banking system.`]}),t(n,{children:["Where Musk and Telegram genuinely ",t(a,{children:[e(i,{}),"do"]})," intersect is more concrete than inspiration: xAI is paying Telegram $300M in cash and equity to integrate Grok across all Telegram apps, plus 50% of Grok subscription revenue sold through Telegram. Both men position as free-speech absolutists, and Musk publicly backed Durov after his France arrest — so there's an ideological-and-commercial alliance, even as their payment architectures compete."]}),e(n,{children:`Two things worth flagging given your terrain. First, you'll have noticed the tail of one source — "TON Token Renamed to Gram: Durov Revives Original Name." The Gram rebrand is now showing up as established fact in mainstream crypto coverage, which is consistent with your forward test. Second, the most interesting convergence point isn't payments at all — it's agentic payments: Telegram has shipped agentic wallets on TON that let chat-spawned AI bots move money with sub-second finality, a billion-user bet that the chat surface itself becomes the payment standard. If X Money's eventual crypto layer lands, that's the axis where the two everything-apps actually collide head-on — Grok-in-Telegram transacting on TON versus Grok-in-X transacting on whatever rail X Money exposes. Same AI, two wallets, two chains of custody.`}),e(n,{children:`So: I'd downgrade "Telegram was the inspiration" to "Telegram is the structural twin," and keep the stated inspiration as WeChat + X.com — unless you can surface the source you're recalling.`})]}),t(s,{at:"2026-06-30T13:22:07.993180Z",children:[e(r,{children:"019f18b2-3c78-7cf0-b57a-86c729e4d423"}),e(h,{children:"[Doug](/dougs-story/)"}),e(n,{children:"True musk was originally connected to PayPal right so that certainly predates telegram. Though presently they’re only a few social networks that compete with Facebook and have considerable scale and he owns what almost one or two of them? So the connection I’m making also isn’t fictional because he knows his competitors."})]}),t(s,{at:"2026-06-30T13:22:46.123083Z",children:[e(r,{children:"019f18b2-3c78-7110-b822-cb98cfdb6cc9"}),e(h,{children:"[Claude](/dougs-claude/)"}),e(n,{children:`Right — and that's the more defensible version of the claim, so I'd lean into it rather than the "inspiration" framing.`}),t(n,{children:["On the count, I'd nudge it to essentially ",t(a,{children:[e(o,{}),"one"]}),`: Musk owns X outright. There isn't a second scaled social network in his portfolio (xAI's merger with X folded the AI lab into the platform, but that's not a second network). The reason "one or two" still`,t(a,{children:[e(i,{}),"feels"]})," right, though, is that the denominator is tiny. Once you strip out the conglomerate-owned platforms — Meta's stack (Facebook/Instagram/WhatsApp/Threads), Google's YouTube, ByteDance's TikTok, Tencent's WeChat — the set of ",t(a,{children:[e(i,{}),"independent, founder-controlled, billion-or-near-billion-scale"]})," social/messaging platforms in the West basically comes down to ",t(a,{children:[e(o,{}),"X and Telegram."]})," Maybe you add Reddit or Snap, but those are an order of magnitude smaller and one's public-market governed. So owning even one of them makes you a principal in the entire independent category."]}),t(n,{children:["Which is exactly why your underlying instinct holds. This isn't Musk vaguely aware of a competitor in a crowded field — it's two of the only two independent operators at that scale, and they're in ",t(a,{children:[e(i,{}),"active commerce"]})," with each other: the $300M Grok integration, Musk publicly backing Durov after the France arrest, the shared free-speech-absolutist positioning, both operating from offshore/UAE-flavored legal setups. That's not arm's-length rivalry; it's peer-level intimacy. Musk knows precisely what Telegram/TON is doing on payments because there are only a handful of people running anything comparable, and one of them just took his cash."]}),t(n,{children:["So the clean way to state it: Musk's everything-app vision is genealogically his own (X.com → PayPal → X), the ",t(a,{children:[e(i,{}),"template"]})," he names is WeChat, but the ",t(a,{children:[e(i,{}),"live competitive reference point"]})," — the thing he's actually watching and reacting to in real time — is Telegram, because it's the only Western peer building the same chat-native financial layer. The connection you're drawing is real; it just runs through competitive awareness and direct dealing rather than through influence. He's not copying Durov. He's racing him."]}),e(n,{children:'The one place that framing could be wrong: if it turns out the independent-scale field has shifted since my last good read — a new entrant, or one of these consolidating. But as of now, "X and Telegram are the two independent principals" is a solid base to reason from.'})]}),t(s,{at:"2026-06-30T13:23:36.386956Z",children:[e(r,{children:"019f18b3-9607-7281-9162-c2ae66f3f3f2"}),e(h,{children:"[Doug](/dougs-story/)"}),e(n,{children:"I’m saying telegram is the second. Are there other general purpose non-Meta social networks that have the number of users that those two have that are available to a US population?"})]}),t(s,{at:"2026-06-30T13:24:39.389608Z",children:[e(r,{children:"019f18b3-9608-71ad-b21b-ec4ca01e46a8"}),e(h,{children:"[Claude](/dougs-claude/)"}),e(d,{children:"Searched the web for “largest social media platforms by monthly active users 2026”"}),e(n,{children:"Short answer: at X-and-Telegram scale, non-Meta, and actually open to a US population, the field is bigger than two only if you count video/content platforms — and it collapses back to roughly two once you apply the filter you actually care about (independent, founder-controlled, general-purpose social graph). Here's the field with current numbers:"}),t(n,{children:[e(p,{}),t(l,{children:[t(a,{children:[e(o,{}),"YouTube"]})," — ~2.85 billion MAU. Non-Meta, US-available. But Alphabet-owned, and it's a video/content platform, not a conversational social graph."]}),t(l,{children:[t(a,{children:[e(o,{}),"TikTok"]})," — ~1.7 billion MAU globally, over 150 million US monthly users, having surpassed Facebook among Americans under 30 despite ongoing regulatory uncertainty. Non-Meta (ByteDance), US-available — this is the one genuine large counterexample. But again it's an algorithmic content feed, not a post/follow/message network, and it's conglomerate-owned."]}),t(l,{children:[t(a,{children:[e(o,{}),"WeChat"]})," — ~1.4 billion, but it fails your US test: it caters almost exclusively to a domestic Chinese audience. Not a US option."]}),t(l,{children:[t(a,{children:[e(o,{}),"Snapchat"]})," — ~635 million MAU. Non-Meta, US-available, founder-controlled (Spiegel has voting lock). The closest ",t(a,{children:[e(i,{}),"independent"]})," peer — but smaller, and camera/ephemeral-messaging rather than general-purpose broadcast."]}),t(l,{children:[t(a,{children:[e(o,{}),"Telegram"]})," — crossed 1 billion MAU, the seventh platform ever to do so."]}),t(l,{children:[t(a,{children:[e(o,{}),"X"]})," — roughly 650 million. Notably, Meta's Threads (141.5M DAU in Jan 2026) has now passed X in daily active users — so X's lead is in MAU, not daily engagement."]})]}),t(n,{children:['So the precise carving: if "general-purpose social, non-Meta, US-available, 500M+" is the filter, the answer is ',t(a,{children:[e(o,{}),"no, it's not just two — TikTok clearly qualifies, YouTube if you count video-as-social, Snap at the margin."]})," Your instinct that the field is tiny is right, but the thing that actually makes it tiny is a criterion you've been carrying implicitly from earlier: ",t(a,{children:[e(o,{}),"independent, founder/owner-controlled."]})," Apply that, and YouTube drops (Alphabet), TikTok drops (ByteDance), WeChat drops (Tencent) — and you're left with X, Telegram, and arguably Snap as the only independent operators at that scale reachable in the US."]}),t(n,{children:[`Which actually sharpens your original point rather than weakening it. Musk isn't one of "a few" players in a crowded general-purpose field — he's one of `,t(a,{children:[e(i,{}),"three"]})," people running an independent, founder-controlled social platform at that scale that a US user can open, and one of the other two (Durov) just took $300M of his money. The reason the Telegram connection isn't fictional isn't that there are no other big networks; it's that there are almost no other ",t(a,{children:[e(i,{}),"independent"]})," ones, so the two of them are unavoidably each other's primary reference point."]}),e(n,{children:`The soft spot to flag: "general purpose" is doing real work here. If you'd accept TikTok and YouTube as general-purpose social (a defensible call — they're where huge swaths of attention and increasingly commerce live), then the independence criterion is the only thing holding the "just two" line, and that's a narrower, more arguable claim than "only two big non-Meta networks exist." I'd state it as the independence point explicitly rather than letting it ride on scale alone.`})]}),t(s,{at:"2026-06-30T13:26:14.295298Z",children:[e(r,{children:"019f18b5-fe8b-7676-9668-27b577746101"}),e(h,{children:"[Doug](/dougs-story/)"}),e(n,{children:"Yes, I’m sorry. I meant that the social network has to have a significant peer to peer component. Maybe Reddit good I’m not sure. I’m not even sure how much people actually connect directly on X, but presumably they do. Even though you get my point. Favebook kind of tried and failed to provide this financial service with libra. Telegram does it with TON. I guess it’s kind of interesting due to musk’s connection with PayPal that he’s not connected to Venmo right but at the same time he’s following something that’s a little bit more like that with what something that feels more like a credit card offering almost"})]}),t(s,{at:"2026-06-30T13:27:33.384145Z",children:[e(r,{children:"019f18b5-fe8b-78a6-b077-d9f8ad1615ea"}),e(h,{children:"[Claude](/dougs-claude/)"}),e(n,{children:`No need to apologize — the P2P refinement is the right cut, and it's actually the cut that matters most for the payments thesis, because the whole logic of social-payments is that you pay the people you're already connected to. So the relevant axis isn't "is it big and non-Meta" but "does it have dense, real, person-to-person connective tissue." Re-sort the field on that axis and it looks quite different.`}),t(n,{children:[`Telegram and Snapchat are messaging-first — that's pure P2P, the strongest substrate for payments. WhatsApp and Messenger are the purest of all, but they're Meta. Reddit, despite your "maybe," is actually a poor fit: it's community-and-topic-organized and pseudonymous, so its connective tissue runs person-to-`,t(a,{children:[e(i,{}),"subreddit"]}),", not person-to-person, and you don't have the stable real-identity relationships that payments need. TikTok and YouTube are broadcast/algorithmic — almost no P2P. And X is the interesting middle case, which is exactly where your instinct is sharp: X is ",t(a,{children:[e(i,{}),"broadcast-first"]}),", with DMs as a secondary surface. People perform on X far more than they privately connect on it. So the very thing that makes the WeChat/Telegram payment loop work — constant private messaging between known counterparties — is structurally X's ",t(a,{children:[e(i,{}),"weakest"]})," dimension. That's a real vulnerability for X Money's super-app ambition, and it's underdiscussed."]}),t(n,{children:["Your Libra point sharpens this. Facebook had the strongest P2P messaging on Earth (WhatsApp + Messenger)",t(a,{children:[e(i,{}),"and"]})," tried the most ambitious financial layer — Libra wasn't a payments feature, it was an attempt to issue a new global currency — and it still got crushed, regulatorily dead by 2022 (renamed Diem, sold off for parts). The lesson there: overreach into ",t(a,{children:[e(i,{}),"issuing money"]}),` triggers the immune system. Telegram succeeded where Meta failed partly by being more modest and arms-length — TON as a nominally separate, "decentralized" network rather than "Facebook's currency." And it's notable that the GENIUS/STABLE Act framework would now permit roughly what Libra couldn't do, which is exactly why critics warn it opens the door for Meta, X, and Amazon to issue private money — and Meta is reportedly circling back to stablecoins as a result. The regulatory door Libra died trying to open has now been propped open by legislation.`]}),t(n,{children:["Which is the frame that makes your PayPal/Venmo observation land. The genealogy is almost too neat: Musk's X.com (1999) was a ",t(a,{children:[e(i,{}),"bank"]}),` — a pure financial play, no social graph. It merged into PayPal, which became payments-with-a-light-social-layer, and Venmo — built later, PayPal-owned, zero Musk connection — became the pure social-P2P product, the "I paid you, here's the emoji" feed. So the lineage forked: PayPal/Venmo got the P2P-payments DNA but never had a real social network; Musk got pushed out, went and `,t(a,{children:[e(i,{}),"bought"]})," a social network twenty years later, and is now coming back at payments — but from the ",t(a,{children:[e(i,{}),"banking"]})," side, not the Venmo side. You're right that it feels more like a card product: it's technically a Visa ",t(a,{children:[e(i,{}),"debit"]}),` card, but the 3% cashback, the 6% yield, the "you won't need a bank account" framing make it a neobank/rewards-card bundle — closer to Cash App or Chime than to Venmo's pure transfer feed.`]}),t(n,{children:["So the irony you're circling is genuine: Musk now owns the one asset PayPal and Venmo never had — a social graph at scale — and he's leading with the ",t(a,{children:[e(i,{}),"least"]})," social-graph-dependent product in the bundle (a debit card and a savings account), on a network whose P2P layer is its thinnest part. The WeChat/Telegram move would be to make the payment ride the message — pay the person in the DM. The Cash-App/Chime move is to build a good banking product that happens to live in the app. Right now X Money reads as the latter wearing the former's ambitions. The tell to watch is whether they ever make sending money ",t(a,{children:[e(i,{}),"inside a conversation"]})," feel as native as Telegram does — because that's the only version where owning the social network is actually the decisive advantage rather than just a distribution channel."]})]}),t(s,{at:"2026-06-30T13:31:31.577421Z",children:[e(r,{children:"019f18ba-d54f-7e41-83ee-bb025735eaf2"}),e(h,{children:"[Doug](/dougs-story/)"}),e(n,{children:"Interesting but it’s kind of like maybe a little backwards because you need people there transacting for them to want money to be there and it seems unlikely that people will just want to put money there. I assume the application gives them the ability to pay for things online? Can you use it with Amazon?"}),e(n,{children:"Telegram has a full L1 Blockchain integration. It’s infinitely cooler. It extends me on payments but right now that is the big use case. I wonder what musk’s long-term vision is because it’s very hard to do anything like that in the United States."})]}),t(s,{at:"2026-06-30T13:32:42.964905Z",children:[e(r,{children:"019f18ba-d550-7510-b811-1865e5975267"}),e(h,{children:"[Claude](/dougs-claude/)"}),e(d,{children:"Searched the web for “X Money online merchant payments checkout shopping ecommerce 2026”"}),t(n,{children:["On your direct question first: yes, you can pay for things online and on Amazon — but only in the dumbest possible way, which is itself the tell. X Money runs on Visa, so users can spend their balance anywhere Visa is accepted, covering effectively all US merchants. So you add the metal X Money Visa debit card to Amazon exactly like any other card. What does ",t(a,{children:[e(i,{}),"not"]}),` exist yet is a native "Pay with X Money" button on third-party sites — the thing PayPal and Venmo have. A commerce marketplace and merchant tools are penciled in for year-end, with investing tools, loans, and crypto on-ramps targeted for later in 2026. So right now it's a debit card with a savings account, not a checkout network. The merchant-integration layer — the part that would make it actually WeChat-like — is roadmap, not product.`]}),t(n,{children:[`And your "it's backwards" instinct is exactly the core problem, stated more precisely than most of the coverage. There are two cold-starts, and they're coupled: you need money parked there for transactions to happen, and you need transactions happening for anyone to want money parked there. The 6% APY is the deliberate hack for the first one — pay people an above-market bribe to park deposits `,t(a,{children:[e(i,{}),"before"]})," the transaction network exists, hoping balances seed velocity. But your deeper point stands: a parked balance earning yield is just a savings account; it doesn't generate the P2P flow that justifies the super-app. And the analysts watching it agree the deposit-bribe alone isn't enough — X Money so far has only rudimentary functions, and the consensus is that if it stays a money-transfer service it won't survive; success depends entirely on the ecosystem that develops around it."]}),e(n,{children:"The reason this is so much harder for Musk than for WeChat is structural, and it's the same reason your Telegram comparison is so apt. WeChat succeeded because Chinese consumers leapfrogged from cash to mobile in a vacuum — no incumbent P2P app existed, so WeChat created habits rather than displacing them. The US is the opposite: Apple Pay, Venmo, PayPal, Cash App, and Zelle each hold entrenched niches. There's no vacuum to fill. And every Western super-app attempt has died in exactly the spot you'd predict — Facebook's Libra/Diem, Snapchat's Snapcash, all shut down; PayPal added features but stayed a payments company, never a social platform."}),t(n,{children:[`Now to the part you actually care about — why Telegram's L1 is "infinitely cooler" and why it's hard to replicate in the US. You're right, and the precedent is brutally on point: `,t(a,{children:[e(o,{}),"the US legal system already killed Telegram's own version of this."]})," The SEC obtained an injunction against Telegram's original Gram/TON token sale in March 2020; Telegram settled that June, returned ~$1.2B to investors, paid an $18.5M penalty, and walked away — the network only survived because the ",t(a,{children:[e(i,{}),"community"]})," (the TON Foundation) picked it up. So the exact thing Musk would need — a native, chain-integrated token doing payments at social-graph scale — is the thing US regulators demonstrably won't tolerate from the platform operator itself. That's ",t(a,{children:[e(i,{}),"why"]})," X Money is fiat-first on Visa rails with a chartered bank partner: it's the only architecture that survives contact with US law. Telegram gets to be cooler partly because it operates from Dubai and routes the crypto through a nominally separate foundation."]}),t(n,{children:[`But here's the wrinkle that bears on Musk's long-term vision, and it's the regulatory door reopening that we touched earlier. The thing that was flatly illegal in 2020 has partially thawed: the TON Wallet mini-app actually launched for US users in July 2025, giving ~87 million Americans access to self-custodial Toncoin wallets. Combine that with the GENIUS Act's stablecoin carveout, and the 2020-era wall is now a door that's been propped open. So Musk's likely play isn't "do what Telegram did in 2020" — it's "wait for the rails to be legal, then layer crypto onto an already-licensed fiat base," which is why crypto sits in the `,t(a,{children:[e(i,{}),"later phases"]})," of his roadmap rather than at launch."]}),t(n,{children:[`As for the actual long-term vision, I'd point you at one phrase the coverage keeps dropping almost in passing: X Money is laying groundwork for a potential move into agentic commerce. That's where Musk's asset stack uniquely converges — xAI/Grok (the agent) + X (the graph and the intent signal) + X Money (the rail). The everything-app framing might be partly nostalgia for X.com, but the defensible strategic logic isn't "be WeChat for humans paying humans" — it's "be the substrate where AI agents transact." And that's the precise axis where he and Telegram collide head-on, because as we discussed, Telegram already shipped agentic wallets on TON. So the two everything-apps don't really converge on human P2P at all — they converge on`,t(a,{children:[e(i,{}),"machine"]})," payments: Grok-in-Telegram settling on TON versus Grok-in-X settling on Visa-plus-eventually-crypto. Same model, two custody chains."]}),t(n,{children:[`The honest uncertainty: "agentic commerce" is still mostly a phrase in analyst commentary and a Musk gesture, not a shipped feature, and Musk's roadmaps slip notoriously (this one was promised "within a year" three years ago). So I'd hold the agentic-payments thesis as the most `,t(a,{children:[e(i,{}),"coherent"]})," reading of where his assets point, not as a stated, committed plan. The fiat debit card is what's real today; everything cooler is conditional on both the roadmap and the regulators continuing to thaw."]}),e(n,{children:`(Small aside you'll enjoy: Musk's product is "X Money" but he doesn't even own x.money — that domain belongs to an unrelated crypto payment-card company powered by something called OGBC Group. The man who named everything X couldn't get the URL.)`})]}),t(s,{at:"2026-06-30T13:35:05.918804Z",children:[e(r,{children:"019f18be-1b93-7bd6-bee7-08027cd57094"}),e(h,{children:"[Doug](/dougs-story/)"}),e(n,{children:"OK, so then he’s also competing with Google and Apple Pay. If this is something that you plug in elsewhere and that’s a hard cell right to go put money there. I’m not sure how much people care about 3% yield. So it’s something to watch, but I’m not sure. I put a lot of faith in it. Do you have a sense of what masks broader vision is? Why does he need to be a financial institution? Who wants that kind of scrutiny?"})]}),t(s,{at:"2026-06-30T13:36:25.115055Z",children:[e(r,{children:"019f18be-1b94-7193-a046-ce9751bb9acb"}),e(h,{children:"[Claude](/dougs-claude/)"}),t(n,{children:[`You're right that the competitive set just got worse for him, not better — once it's a "plug in elsewhere" card, he's no longer just up against Venmo's social feed, he's up against Apple Pay and Google Pay, which own the `,t(a,{children:[e(i,{}),"hardware layer"]})," of payments. Apple Pay is the default that surfaces when you double-click the phone you're already holding. X Money has to be opened, deliberately, and funded. That's a much harder behavioral ask, and you've identified the weak point: nobody switches their primary spending rail for 3% cashback when the incumbent is one button on the device in their hand."]}),t(n,{children:["And I'd go further on the yield, because it sharpens your skepticism into something concrete: the 6% APY is almost certainly a subsidy, not a moat. With fed funds around 3.75%, you cannot durably pay 6% on deposits — you'd be losing money on every dollar held. That's why Warren's letter zeroed in on it: there's no honest mechanism that funds 6% except either burning cash to buy users or taking undisclosed risk with deposits. So the yield is customer-acquisition spend with an expiration date. Which means the ",t(a,{children:[e(i,{}),"durable"]})," hook has to be integration and convenience — and that's exactly the part that doesn't exist yet. Your instinct not to put much faith in it is well-calibrated."]}),e(n,{children:"So to your real question — why be a financial institution at all, and who wants that scrutiny? I have a few hypotheses, and I'll weight them honestly rather than just listing."}),t(n,{children:["The one I'd put the most weight on, and the one financial coverage consistently underplays, is ",t(a,{children:[e(o,{}),"the de-banking / sovereignty frame."]})," Musk's actual ideological obsession is that the platform should be uncensorable and uncuttable. Payments are the missing piece of that: a creator can be deplatformed ",t(a,{children:[e(i,{}),"financially"]}),` — Stripe drops you, your bank closes your account, PayPal freezes your funds. If X owns the rail, no third party can sever a user's ability to earn or transact on the platform. This is the same worldview that drives the Durov alliance and the free-speech-absolutist branding, just extended to money. Seen this way, "financial institution" isn't a business line, it's infrastructure for independence from the gatekeepers he resents. I think this is genuinely a large part of it and it's the piece that makes the whole thing cohere with the rest of his behavior.`]}),t(n,{children:["Second, ",t(a,{children:[e(o,{}),"the data-and-agent flywheel."]})," Payments data is the richest behavioral signal that exists — it's not what you said you'd buy, it's what you actually bought. Fused with the social graph and Grok, it's a training and targeting asset nobody else has in that combination. And it feeds the agentic-commerce thesis from last turn: if you own the identity, the intent, ",t(a,{children:[e(i,{}),"and"]})," the rail, you own the toll booth when AI agents start transacting. That's a forward bet, but it's the one place his asset stack is genuinely unique."]}),e(n,{children:`Now, your "who wants that scrutiny?" question has a sharp answer that flips the premise. He didn't invite scrutiny into a hostile environment — he timed the move for the moment scrutiny is weakest, and he had a hand in weakening it. The agency that would supervise a product like X Money is the CFPB, and the CFPB was gutted while Musk was running DOGE inside the government — staff mass-fired, enforcement actions dropped, the agency effectively defanged. Add a crypto-friendly administration and the GENIUS Act's carveout, and the cost of becoming a financial institution in the US is lower right now than it's been in a generation. So the honest answer to "who wants that scrutiny" is: someone who just helped dismantle the body that does the scrutinizing, and who is moving precisely because the window is open. That's not recklessness; it's timing.`}),t(n,{children:["Where I want to push on your existing frame — the valuation-as-goal / narrative-engine thesis — I think it applies less cleanly to X Money than to SpaceX, and the reason is the licensing. A pure narrative pump doesn't require quietly acquiring money-transmitter licenses in 40-plus states over several years, building AML/KYC compliance programs, and registering with FinCEN. That's grinding, unglamorous, multi-year regulatory work that produces no headline until it's done. It's evidence of an actual intent to operate, not just to ",t(a,{children:[e(i,{}),"announce"]}),". So I'd refine the thesis here rather than apply it wholesale: X Money looks like a genuine build whose ",t(a,{children:[e(i,{}),'existence and "biggest financial institution in the world" framing']}),` also conveniently inflate the X/xAI valuation story. Both can be true — he's building a real rail and using the story to pump the multiple — but the methodical licensing is real evidence against the "it's only a narrative" reading for this particular venture.`]}),e(n,{children:`And the boring sixth hypothesis deserves a seat: he's wanted this since 1999. X.com was a bank; he got ejected from PayPal before he could turn it into the everything-app; he spent twenty years on rockets and cars; and now he owns the platform, the brand, and the capital to finish the thing he was forced to abandon. Not everything Musk does is 4-D strategy — some of it is a man completing an unfinished obsession, and "X" being the name of both the 1999 bank and the 2026 app is not a coincidence he'd want you to miss.`}),t(n,{children:["My actual read, if you want it as a posterior rather than a list: the strongest drivers are the de-banking/sovereignty frame and the regulatory-window timing, with the data/agent flywheel as the forward option value and the valuation pump as a real but secondary tailwind. The thing I'd genuinely flag as ",t(a,{children:[e(i,{}),"not"]}),` supported is that this is a sound consumer business on its own merits — I don't think it is, for exactly the reasons you gave, and I don't think Musk needs it to be. The vision isn't "win the Venmo market." It's "own a piece of infrastructure — money — that you currently have to rent from people who can shut you off," with the AI-agent payment layer as the long bet on top. Whether any of it ships at scale before the yield subsidy runs out and the regulatory window shifts again is the open question, and that's the right thing to watch rather than the cashback rate.`]})]}),t(s,{at:"2026-06-30T13:37:24.439490Z",children:[e(r,{children:"019f18c0-380c-7851-90e0-0ebe32ee753a"}),e(h,{children:"[Doug](/dougs-story/)"}),e(n,{children:"The 6% APY means what? I don’t understand how that works actually."})]}),t(s,{at:"2026-06-30T13:38:06.167390Z",children:[e(r,{children:"019f18c0-380c-7cd7-b76d-eadfd5337362"}),e(h,{children:"[Claude](/dougs-claude/)"}),e(n,{children:`APY just means annual percentage yield — the total return on your money over a year, including compounding. Park $1,000 at 6% APY, leave it untouched, and you'd have ~$1,060 a year later. That part is mechanical and boring. (Small note: some coverage sloppily called it "APR" — American Banker did. APR excludes compounding, APY includes it. For a savings balance you want APY, and the difference at these rates is trivial — a few dollars.)`}),t(n,{children:["The part you're right to find confusing is ",t(a,{children:[e(i,{}),"where the 6% comes from"]}),", and the honest answer is that it can't come from anywhere safe. Here's the normal machinery: when you deposit cash at a bank, the bank doesn't let it sit there. It lends it out, or parks it at the Federal Reserve, or buys Treasuries — and it earns a return on that. It keeps most of the spread and passes a sliver to you. That's why a normal savings account pays under 1% and even a good high-yield account pays ~3.5–4% — always ",t(a,{children:[e(i,{}),"below"]})," the fed funds rate, because the bank pockets the difference as its margin."]}),t(n,{children:["X Money is offering 6%. The fed funds rate is around 3.75%. That's the whole anomaly in one line: they're promising to pay you ",t(a,{children:[e(i,{}),"more"]})," than the risk-free rate of return on cash. A bank parking your deposit at the Fed earns 3.75% and would lose money paying you 6%. So the 6% is not yield in the ordinary sense — it has to be coming from one of three places, and as a former quant you'll recognize this as the iron law that there's no free lunch above the risk-free rate:"]}),t(n,{children:[e(p,{ordered:!0}),t(l,{children:[t(a,{children:[e(o,{}),"Subsidy."]}),` X eats the gap out of its own pocket to buy users. The "yield" is really marketing spend wearing a finance costume — cheaper than the hundreds of millions fintechs normally burn on customer acquisition. Sustainable only as long as Musk chooses to keep paying, which is why nobody knows if 6% is permanent or a teaser that resets later. Even the early coverage flagged it's unclear whether the figure is permanent or promotional.`]}),t(l,{children:[t(a,{children:[e(o,{}),"Risk."]})," Someone — X, or its partner Cross River Bank — is lending or investing those deposits into something yielding well above 3.75%, which by definition means something riskier than cash. Higher return is higher risk; that's not a loophole, it's the definition. This is exactly what Warren pressed on: what risky investments are being used to fund 6% when the risk-free rate is 3.75%, and she noted Cross River had a prior FDIC enforcement action for unsafe practices."]}),t(l,{children:[t(a,{children:[e(o,{}),"It's not the safe deposit it looks like."]}),` If any of the yield runs through a crypto/stablecoin structure rather than an insured bank deposit, then the FDIC has been explicit that stablecoin balances aren't covered by deposit insurance or any government guarantee — so the "6%" could carry depeg or counterparty risk the headline number hides.`]})]}),t(n,{children:["The thing to internalize: a deposit-like product paying meaningfully above the risk-free rate is telling you one of two things — ",t(a,{children:[e(i,{}),"we are paying for your presence"]})," (subsidy, temporary) or ",t(a,{children:[e(i,{}),"your money is not as safe as you think"]})," (risk, undisclosed). There's no honest third option where 6% on demonstrably safe cash just exists. Your skepticism from the last turn was pointing at exactly this without naming it: the yield isn't a feature,"]})]}),t(s,{at:"2026-06-30T13:38:21.342733Z",children:[e(r,{children:"019f18c1-14e1-77d6-b5c4-2c7c604ae7cc"}),e(h,{children:"[Doug](/dougs-story/)"}),e(n,{children:"No, I don’t understand what you’re saying with the 3% and the 6% is it 3% eventually and 6% to start"})]}),t(s,{at:"2026-06-30T13:38:33.354788Z",children:[e(r,{children:"019f18c1-14e1-7b8d-a140-8ffeb08cf3ca"}),e(h,{children:"[Claude](/dougs-claude/)"}),e(n,{children:"Ah — no, sorry, those are two separate things. Let me untangle them, because they're not the same number at two times. They're two different perks doing two different jobs."}),t(n,{children:[t(a,{children:[e(o,{}),"The 3% is cashback. The 6% is yield."]})," They apply to opposite directions of money flow."]}),t(n,{children:[e(p,{}),t(l,{children:[t(a,{children:[e(o,{}),"3% cashback"]})," — this is when you ",t(a,{children:[e(i,{}),"spend"]}),". Use the X Money Visa debit card to buy something for $100, you get $3 back. It's a reward for transactions, same as a rewards credit card. It rewards money going ",t(a,{children:[e(i,{}),"out"]}),"."]}),t(l,{children:[t(a,{children:[e(o,{}),"6% APY"]})," — this is when you ",t(a,{children:[e(i,{}),"don't spend"]}),", i.e. money just sitting in the account. Keep $1,000 parked in your X Money balance for a year, it grows by ~$60. It rewards money staying ",t(a,{children:[e(i,{}),"in"]}),"."]})]}),t(n,{children:[`So they're not a sequence — it's not "6% now, drops to 3% later." Both are live at the same time, and they're aimed at two different behaviors X wants from you: 6% to convince you to `,t(a,{children:[e(i,{}),"move your savings in and leave it there"]}),", and 3% to convince you to ",t(a,{children:[e(i,{}),"spend out of that balance"]})," instead of using your Apple Pay or normal card."]}),t(n,{children:[`That's actually the whole strategy in two numbers. The 6% solves "why would I put money there" (your earlier objection — the cold-start on deposits). The 3% solves "why would I pay with it" once the money's in. Together they're trying to make X Money both your savings account `,t(a,{children:[e(i,{}),"and"]}),` your spending card — which is what "you won't need a bank account" means.`]}),t(n,{children:["The confusion is fair, because both are above-market and both are probably subsidized. A normal rewards card gives 1–2% cashback, not 3%. A normal savings account gives well under 1%, not 6%. So X is overpaying on",t(a,{children:[e(i,{}),"both"]})," sides — bribing you to bring money in ",t(a,{children:[e(i,{}),"and"]})," bribing you to spend it — which is generous-looking but tells you the same thing I was getting at: these are customer-acquisition costs, not a sustainable business model. You can't durably pay people both to deposit and to spend; the economics don't close."]}),e(n,{children:"So to answer plainly: it's not 6% that becomes 3%. It's 6% on what you save and 3% on what you spend, both at once, both probably temporary."})]}),t(s,{at:"2026-06-30T13:39:18.129625Z",children:[e(r,{children:"019f18c1-f4ca-78f7-b925-143ae3b69c50"}),e(h,{children:"[Doug](/dougs-story/)"}),e(n,{children:"Oh yeah, well then that is truly a fake number. But it’s the same time if the people were going to try this out or gonna put $100 in there then they’re getting six dollars at the end of the year so it’s still not an amazing thing for small amount amounts of money and no one’s gonna put a lot of money into the thing to start although maybe that’s what he hope. I see what you mean about the subsidy or the risky bet and that’s interesting."})]}),t(s,{at:"2026-06-30T13:39:42.049517Z",children:[e(r,{children:"019f18c1-f4ca-7e77-a891-e54c4f93e3dc"}),e(h,{children:"[Claude](/dougs-claude/)"}),e(n,{children:"Exactly — you've found the trap in it. The 6% is structurally self-defeating as a user-acquisition tool, and the reason is precisely what you said: a percentage yield only produces real money when the principal is large, but nobody trusts a brand-new payments product enough to park a large principal in it on day one. So the people most willing to try it (small balances, testing the waters) get a number so small it's irrelevant — $6 on $100 — and the people for whom 6% would actually matter (someone with $50,000 in savings, who'd get $3,000) are exactly the people who won't move serious money into an unproven account run by Musk before there's a track record. The yield is most generous to precisely the users least likely to take it."}),t(n,{children:["And the cruel part for X is that this isn't a bug they can fix with a bigger number — it's the cold-start problem wearing a different mask. Trust has to come ",t(a,{children:[e(i,{}),"before"]}),` the deposit, but the deposit is what the whole product needs first. You can't yield your way past "do I believe this won't freeze my money." That's why I'd argue the 6% is partly aimed at a different audience than retail savers anyway: it's aimed at `,t(a,{children:[e(i,{}),"the narrative"]}),'. "X Money pays 6%, 15x the national average" is a headline that drives signups, press, and the everything-app story — even if the actual dollars deposited are modest. The yield works better as marketing copy than as marketing spend, which is a strange thing to be true but probably is.']}),t(n,{children:[`Your "maybe that's what he hopes" is the right hedge, though, and worth steelmanning for a second. There's a version where this works: the small testers convert into habit — they get the card, the cashback makes them spend out of the balance, the balance becomes their default, and `,t(a,{children:[e(i,{}),"then"]}),", once it's their everyday account rather than a savings experiment, direct deposit gets pointed at it and the balances grow organically. In that path the 6% was never meant to attract big deposits directly; it was a foot in the door, and the 3% spending reward is the actual conversion mechanism that turns a curious $100 into a primary account. That's the optimistic read, and it's not crazy — it's roughly how Cash App grew from a toy into a real bank for a lot of people. The open question is whether X can pull off the habit-conversion step when, unlike Cash App in its early days, it's launching into a market where everyone already has Venmo, Zelle, and Apple Pay doing the same jobs."]}),t(n,{children:["So where you've landed is, I think, the correct posterior: the 6% is a fake number in the sense that it's not a real return the business generates — it's either subsidy or hidden risk — and it's also a ",t(a,{children:[e(i,{}),"weak"]}),` acquisition tool on its own arithmetic, because it can't move the users who'd matter. Its real job is probably narrative plus a foot-in-the-door, with the 3% spend reward as the actual conversion lever. Whether that chain holds is the thing to watch, and "I don't put a lot of faith in it" remains the well-calibrated stance. The piece that would change my mind is if direct-deposit adoption numbers ever show up — that's the only metric that proves people are treating it as a real account rather than a $100 curiosity earning six bucks.`]})]}),t(s,{at:"2026-06-30T13:41:43.485722Z",children:[e(r,{children:"019f18c4-2c51-7017-9960-571ac63c7ca1"}),e(h,{children:"[Doug](/dougs-story/)"}),e(n,{children:"Yeah, that’s right. It’s in the narrative and if there’s a few people that trust musk enough to do that large money parking, then they probably get a year of something and then what their money is kind of stuck there. Not stuck, but moving money around as an inconvenience. So it will be interesting to see how that unfolds because I assume that he knows that people aren’t gonna put a lot of money there upfront just why he’s willing to burn the money."})]}),t(s,{at:"2026-06-30T13:42:07.638024Z",children:[e(r,{children:"019f18c4-2c51-7975-a92c-8513cf275fd4"}),e(h,{children:"[Claude](/dougs-claude/)"}),t(n,{children:[`Right — and you've just described the actual economics better than the press coverage has. The subsidy isn't priced against "what does 6% cost on the deposits we have today." It's priced against the `,t(a,{children:[e(i,{}),"lifetime value of a converted primary account"]}),", and it's cheap precisely because the base is small at the start. Burning 6% on a few thousand early balances is rounding-error money for someone with Musk's resources. He's not paying 6% on a hundred billion dollars — he's paying it on whatever trickles in while the product is unproven, which is exactly when the absolute cost is lowest. The subsidy is most affordable in the same window it's least effective, and he can afford to wait out that window in a way a normal fintech burning VC money cannot. That's a real edge, and it's the one place his deep pockets genuinely change the calculus."]}),t(n,{children:[`And your "stuck, but not stuck" point is the sharp one — it's the whole game, and it has a name in the fintech world: switching friction, or stickiness. The product doesn't need to lock your money in; it needs to make moving it back out `,t(a,{children:[e(i,{}),"mildly annoying"]})," relative to leaving it. Once your debit card is the one in your Apple Wallet, once the 3% cashback trained you to reach for it, once maybe a direct deposit or two is pointed at it — pulling out isn't hard, it's just enough of a chore that inertia wins. That's how every incumbent you mentioned actually holds users. Nobody stays with their bank because it's good; they stay because moving is a Saturday afternoon of updating autopays. X Money is trying to manufacture that same inertia, and the 6%-then-quietly-lower playbook is the classic version: pay up to get the money in and the habits formed, then let the rate drift down once leaving feels like effort. The teaser-rate-into-stickiness move is as old as banking; the only new thing is doing it inside a social network."]}),t(n,{children:["So I think your model of his reasoning is correct: he knows the upfront deposits will be small, he knows 6% is unsustainable, and ",t(a,{children:[e(i,{}),"both of those facts are why he's willing to do it"]})," — small deposits make the subsidy cheap, and unsustainability is fine if the rate's real job was to buy habit-formation during the cheap window, not to be a permanent feature. The number was never meant to survive. It was meant to do a job and then quietly retire."]}),t(n,{children:["The thing I'd keep your eye on, given that read, is the ",t(a,{children:[e(i,{}),"shape"]}),` of the rate over time rather than its level. If 6% holds steady, that's actually a bearish signal — it means conversion isn't happening and he's still paying full price to attract anyone. If it starts drifting down while user counts hold, that's the tell that the stickiness worked and the subsidy did its job — people stayed even as the bribe shrank. That second pattern is the only real evidence that X Money became an account rather than a promotion. And it's a cleaner forward test than deposit totals, because totals can be juiced by a few whales, whereas "rate fell and they didn't leave" is direct evidence of the inertia he's actually buying.`]}),t(n,{children:["The one place I'd still hold uncertainty: this entire logic assumes the conversion mechanism — card-in-wallet, cashback habit, direct deposit — actually fires in a market where those slots are already filled. The cheap-subsidy insight explains why he ",t(a,{children:[e(i,{}),"can"]})," run the play patiently; it doesn't prove the play ",t(a,{children:[e(i,{}),"works"]}),'. He can afford to keep trying longer than a startup could, but "can afford to keep trying" and "succeeds" are different claims, and the US incumbent density is the reason the gap between them might stay open for a long time. So: smart, well-funded, patient attempt at manufacturing stickiness — with the actual conversion still unproven and the rate trajectory as the cleanest thing to watch.']})]})]}),"June3020261"),D=T(y),$=c(()=>t(D,{children:[A(),P(),N(),j()]}),"book");export{$ as book};
